// netlify/functions/validate-coach.js
var { createClient } = require_dist4();
var { Resend } = require_dist5();
exports.handler = async (event) => {
  if (event.httpMethod !== "POST") {
    return { statusCode: 405, body: "Method Not Allowed" };
  }
  const supabase = createClient(
    process.env.SUPABASE_URL,
    process.env.SUPABASE_SERVICE_ROLE_KEY
    // bypasse RLS
  );
  const resend = new Resend(process.env.RESEND_API_KEY);
  const { coachId, validated, adminNote } = JSON.parse(event.body);
  const { data: coach, error } = await supabase.from("coaches").update({ validated, admin_notes: adminNote || "" }).eq("id", coachId).select("*, profiles(*)").single();
  if (error) return { statusCode: 500, body: JSON.stringify({ error: error.message }) };
  const email = coach.profiles?.email;
  if (email) {
    await resend.emails.send({
      from: "PadelBook <noreply@padelbook.fr>",
      to: email,
      subject: validated ? "\u2705 Profil valid\xE9 \u2014 PadelBook" : "\u274C Profil refus\xE9 \u2014 PadelBook",
      html: validated ? `<h2>F\xE9licitations ${coach.nom} !</h2><p>Votre profil coach a \xE9t\xE9 valid\xE9. Vous \xEAtes maintenant visible par les joueurs sur PadelBook.</p>` : `<h2>Profil non valid\xE9</h2><p>Votre profil coach n'a pas pu \xEAtre valid\xE9.${adminNote ? `<br>Raison : ${adminNote}` : ""}</p><p>Contactez-nous pour plus d'informations.</p>`
    });
  }
  return { statusCode: 200, body: JSON.stringify({ ok: true }) };
};
